function longestBrick(s1: string, s2: string): string {
  const builds = (b: string, s: string) => s.length % b.length === 0 && b.repeat(s.length / b.length) === s;
  for (let len = Math.min(s1.length, s2.length); len >= 1; len--) {
    const b = s1.slice(0, len);
    if (builds(b, s1) && builds(b, s2)) return b;
  }
  return "";
}

