    def longestBrick(self, s1: str, s2: str) -> str:
        def builds(b, s):
            return len(s) % len(b) == 0 and b * (len(s) // len(b)) == s

        for length in range(min(len(s1), len(s2)), 0, -1):
            b = s1[:length]
            if builds(b, s1) and builds(b, s2):
                return b
        return ""

