function longestBrick(s1: string, s2: string): string {
  if (s1 + s2 !== s2 + s1) return "";
  const gcd = (a: number, b: number): number => (b === 0 ? a : gcd(b, a % b));
  return s1.slice(0, gcd(s1.length, s2.length));
}

